-- Three sample posts, so the book has pages before you write your own.
-- Generated by scripts/make-seed.ts. Delete them from the admin area whenever you like.

insert into public.posts
  (slug, title, excerpt, content, cover_image_url, cover_image_alt, tags, seo_description, status, published_at, reading_minutes)
values
  (
    'how-i-screen-for-quality-compounders',
    'How I Screen for Quality Compounders',
    'A good stock screen does not find winners for you. It removes the businesses you should never spend an evening on. Here are the five filters I run before I read a single annual report.',
    '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is a sample post so you can see how the book and the reading view feel. Replace it with your own writing from the admin area."}]},{"type":"paragraph","content":[{"type":"text","text":"A good stock screen does not find winners for you. It removes the businesses you should never spend an evening on. Most of the market is made up of companies that earn less than their cost of capital, and no amount of clever valuation work turns those into great investments."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The five filters"}]},{"type":"paragraph","content":[{"type":"text","text":"First, return on invested capital above fifteen percent for at least seven of the last ten years. One good year proves nothing. A decade of good years suggests something structural is protecting the business."}]},{"type":"paragraph","content":[{"type":"text","text":"Second, revenue that has grown without the share count growing alongside it. Growth that is paid for by issuing new shares belongs to somebody else."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"The screen is a sieve, not a compass. It tells you where not to dig."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Third, debt that could be repaid from three years of free cash flow. Fourth, gross margins that have been stable or rising. Fifth, a business I could explain to a friend in two sentences."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens next"}]},{"type":"paragraph","content":[{"type":"text","text":"From several thousand listed companies this usually leaves a few dozen. Those are the ones that earn a slow read of the annual report, and that is where the real work begins."}]}]}'::jsonb,
    '/covers/compounders.svg',
    'A rising line chart over a soft mint background with a pale sun',
    array['Stock Picking', 'Fundamentals']::text[],
    'A good stock screen does not find winners for you. It removes the businesses you should never spend an evening on. Here are the five filters I run before I…',
    'published',
    '2026-11-09T08:00:00Z'::timestamptz,
    1
  ),
  (
    'reading-a-cash-flow-statement-in-ten-minutes',
    'Reading a Cash Flow Statement in Ten Minutes',
    'Profit is an opinion, cash is a fact. The cash flow statement is the shortest route to seeing whether a company''s reported earnings turn into money you could actually spend.',
    '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is a sample post. It shows how a mid-length article with headings and a quote looks in the reading view."}]},{"type":"paragraph","content":[{"type":"text","text":"Profit is an opinion, cash is a fact. The income statement is full of estimates: how long a machine will last, how many customers will pay late, what a brand is worth. The cash flow statement simply records what came in and what went out."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Start at the bottom of the first section"}]},{"type":"paragraph","content":[{"type":"text","text":"Cash from operations is the number to find first. Compare it with net income over five years. If profits keep rising while operating cash stays flat, something is being booked as earned before it has been collected."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Then subtract what it costs to stand still"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital expenditure sits in the investing section. Operating cash minus capital expenditure gives free cash flow, which is the money left for dividends, buybacks, debt repayment and acquisitions."}]},{"type":"codeBlock","attrs":{"language":"python"},"content":[{"type":"text","text":"def free_cash_flow(operating_cash, capital_expenditure):\n    return operating_cash - capital_expenditure\n\n# figures in millions\nmargin = free_cash_flow(1200, 300) / 4800  # 0.1875, or about 19%"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"If a business needs all of its cash just to stay where it is, the owners are working for the machines."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Finally, read the financing section to see where that free cash goes. The pattern over several years tells you more about management than any letter to shareholders."}]}]}'::jsonb,
    '/covers/cash-flow.svg',
    'Blue bars rising from left to right with two flowing lines above them',
    array['Analysis', 'Beginners']::text[],
    'Profit is an opinion, cash is a fact. The cash flow statement is the shortest route to seeing whether a company''s reported earnings turn into money you could…',
    'published',
    '2026-10-27T08:00:00Z'::timestamptz,
    1
  ),
  (
    'margin-of-safety-why-price-still-matters',
    'Margin of Safety: Why Price Still Matters',
    'A wonderful business bought at the wrong price can still be a poor investment. Margin of safety is the simple habit of leaving room for your own mistakes.',
    '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is a sample post. Your own posts will appear here automatically, newest first, as soon as you publish them."}]},{"type":"paragraph","content":[{"type":"text","text":"A wonderful business bought at the wrong price can still be a poor investment. The quality of the company and the quality of the purchase are two separate questions, and it is easy to answer the first and forget the second."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Room for error"}]},{"type":"paragraph","content":[{"type":"text","text":"Every valuation rests on guesses about the future. Margin of safety means paying noticeably less than your estimate of value, so that the investment can still work out if some of those guesses are wrong."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"You do not need to know a man''s exact weight to know that he is heavy."}]}]},{"type":"paragraph","content":[{"type":"text","text":"How wide the margin should be depends on how predictable the business is. A steady consumer brand might deserve a smaller discount than a cyclical manufacturer whose profits swing with the economy."}]}]}'::jsonb,
    '/covers/margin-of-safety.svg',
    'Two lines on a warm background with a shaded gap between value and price',
    array['Valuation', 'Risk']::text[],
    'A wonderful business bought at the wrong price can still be a poor investment. Margin of safety is the simple habit of leaving room for your own mistakes.',
    'published',
    '2026-10-12T08:00:00Z'::timestamptz,
    1
  )
on conflict (slug) do nothing;
